using StemPasswordGenerator.Models;

namespace StemPasswordGenerator.Services;

public static class UiStrings
{
    public static event EventHandler? LanguageChanged;

    public static AppLanguage Language { get; private set; } = AppLanguage.English;

    public static void SetLanguage(AppLanguage language)
    {
        if (Language == language)
        {
            return;
        }

        Language = language;
        LanguageChanged?.Invoke(null, EventArgs.Empty);
    }

    public static string Get(string key)
    {
        if (Catalog.TryGetValue(key, out var pair))
        {
            return Language == AppLanguage.Spanish ? pair.Es : pair.En;
        }

        return key;
    }

    public static string Format(string key, params object[] args) => string.Format(Get(key), args);

    public static IReadOnlyList<(string Key, string En, string Es)> Snapshot() =>
        Catalog.Select(static pair => (pair.Key, pair.Value.En, pair.Value.Es)).ToList();

    private readonly record struct Pair(string En, string Es);

