        ["ShamirCardKeepApart"] = new("Keep this card apart from the other two. Do not photograph all three together.", "Guarda esta tarjeta aparte de las otras dos. No fotografíes las tres juntas."),
        ["ShamirSaved"] = new("Three Shamir card files saved. Print them, then keep them in different places.", "Se guardaron tres archivos de tarjetas Shamir. Imprímelas y sepáralas."),
        ["ShamirRecoverButton"] = new("Recover with 2 cards", "Recuperar con 2 tarjetas"),
        ["ShamirRecoverHint"] = new("Pick any two printed Shamir card files for this person. Stem reconstructs the master password on this PC only.", "Elige dos archivos de tarjetas Shamir de esta persona. Stem reconstruye la contraseña maestra solo en este PC."),
        ["ShamirRecovered"] = new("Master password reconstructed from Shamir cards.", "Contraseña maestra reconstruida con las tarjetas Shamir."),
        ["ShamirNeedTwo"] = new("Need any 2 Shamir cards.", "Hacen falta 2 tarjetas Shamir."),
        ["ShamirTooLong"] = new("That master password is too long to print on Shamir cards.", "Esa contraseña maestra es demasiado larga para imprimirla en tarjetas Shamir."),
        ["ShamirWrongPassword"] = new("That is not this vault's master password.", "Esa no es la contraseña maestra de esta bóveda."),
        ["ShamirUnrecognized"] = new("Those files are not matching Stem Shamir cards.", "Esos archivos no son tarjetas Shamir de Stem que coincidan."),
        ["ShamirCouldNotSave"] = new("Could not save the Shamir card files.", "No se pudieron guardar los archivos de las tarjetas Shamir."),
        ["RecoveryPhraseTitle"] = new("Your 7-word recovery phrase", "Tu frase de recuperación de 7 palabras"),
        ["RecoveryPhraseOnceHeader"] = new("Write these 7 words now — Stem will not show them again", "Anota estas 7 palabras ahora — Stem no las volverá a mostrar"),
        ["RecoveryPhraseOnceBody"] = new("This random phrase is issued once while you configure recovery. It is not the master password. Stem stores only an Argon2id hash. To reset a forgotten master you will need Windows Hello plus these 7 words (or Hello plus the recovery key).", "Esta frase al azar se emite una sola vez al configurar la recuperación. No es la contraseña maestra. Stem solo guarda un hash Argon2id. Para resetear una maestra olvidada harán falta Windows Hello y estas 7 palabras (o Hello y la recovery key)."),
        ["RecoveryPhraseConfirmHeader"] = new("Type the 7 words in order to confirm", "Escribe las 7 palabras en orden para confirmar"),
        ["RecoveryPhraseConfirmHint"] = new("word word word word word word word", "palabra palabra palabra palabra palabra palabra palabra"),
        ["RecoveryPhraseMismatch"] = new("Those words do not match. Copy the 7 words in order.", "Esas palabras no coinciden. Copia las 7 palabras en orden."),
        ["RecoveryPhraseConfirmed"] = new("I have the 7 words", "Ya tengo las 7 palabras"),
        ["RecoveryLaterButton"] = new("Configure later in Protect", "Configurar luego en Proteger"),
        ["RecoveryLater"] = new("Recovery is not on yet. Open Protect to issue the 7-word phrase once.", "La recuperación aún no está. Abre Proteger para emitir la frase de 7 palabras una vez."),
        ["RecoveryKitBody"] = new("Stem will never show these again. It stores only Argon2id hashes, not the key or the phrase. You need Windows Hello plus the key, or Windows Hello plus the 7-word phrase, to set a new master password.", "Stem no los volverá a mostrar. Solo guarda hashes Argon2id, no la key ni la frase. Para poner una maestra nueva hace falta Windows Hello más la key, o Windows Hello más la frase de 7 palabras."),
        ["RecoveryKeyHeader"] = new("Recovery key (once)", "Recovery key (una vez)"),
        ["RecoveryPhraseHeader"] = new("Recovery phrase (7 words, not the master)", "Frase de recuperación (7 palabras, no es la maestra)"),
        ["RecoverySaved"] = new("I saved these in a safe place", "Los guardé en un sitio seguro"),
        ["RecoveryExport"] = new("Export file…", "Exportar archivo…"),
        ["RecoveryExportHello"] = new("Protect the file with Windows Hello", "Proteger el archivo con Windows Hello"),
        ["RecoveryExportPassword"] = new("Protect the file with an extra password", "Proteger el archivo con una contraseña extra"),
        ["RecoveryExportPlain"] = new("Unprotected text file (weaker)", "Archivo de texto sin proteger (más débil)"),
        ["RecoveryExportPlainTitle"] = new("Export without protection?", "¿Exportar sin proteger?"),
        ["RecoveryExportPlainBody"] = new("Anyone who opens that file can reset this vault if they also pass Windows Hello on this PC. Prefer Hello or an extra password.", "Quien abra ese archivo puede resetear esta bóveda si también pasa Windows Hello en este PC. Mejor Hello o una contraseña extra."),
        ["RecoveryExportPasswordTitle"] = new("Extra password for the recovery file", "Contraseña extra del archivo de recuperación"),
        ["RecoveryExportPasswordHeader"] = new("File password (12+ characters)", "Contraseña del archivo (12+ caracteres)"),
        ["RecoveryExportPasswordHint"] = new("This password is only for the export file. It is not the master password and not the 7-word phrase.", "Esta contraseña es solo del archivo exportado. No es la maestra ni la frase de 7 palabras."),
        ["RecoveryExported"] = new("Recovery file saved. Stem still does not keep a plaintext copy.", "Archivo de recuperación guardado. Stem sigue sin guardar una copia en texto plano."),
        ["RecoveryCouldNotExport"] = new("Could not save the recovery file.", "No se pudo guardar el archivo de recuperación."),
        ["RecoveryProtectTitle"] = new("Recovery options", "Opciones de recuperación"),
        ["RecoveryProtectHint"] = new("When you configure recovery, Stem issues a random 7-word phrase once. Write it down; it will not be shown again. Stem keeps an Argon2id hash only. Resetting a forgotten master needs Windows Hello plus that phrase, or Hello plus the recovery key, then a new master that re-encrypts the vault.", "Al configurar la recuperación, Stem emite una frase aleatoria de 7 palabras una sola vez. Anótala; no se vuelve a mostrar. Stem solo guarda un hash Argon2id. Resetear una maestra olvidada pide Windows Hello más esa frase, o Hello más la recovery key, y luego una maestra nueva que vuelve a cifrar la bóveda."),
        ["RecoveryStatusOn"] = new("Recovery hashes are on this PC. The key and phrase are not stored in plaintext.", "Los hashes de recuperación están en este PC. La key y la frase no se guardan en texto plano."),
        ["RecoveryStatusOff"] = new("No recovery kit yet. Create one while you still know the master password.", "Aún no hay kit de recuperación. Créalo mientras aún sepas la maestra."),
        ["RecoveryCreate"] = new("Configure recovery — issue 7-word phrase once", "Configurar recuperación — emitir frase de 7 palabras una vez"),
        ["RecoveryReplace"] = new("Replace recovery phrase (issued once)", "Sustituir frase de recuperación (se emite una vez)"),
        ["RecoveryReplaceTitle"] = new("Replace recovery kit?", "¿Sustituir el kit de recuperación?"),
        ["RecoveryReplaceBody"] = new("The old recovery key, phrase, and export files will stop working. Stem will show the new secrets once and store only hashes.", "La recovery key, la frase y los archivos exportados viejos dejarán de servir. Stem mostrará los secretos nuevos una vez y solo guardará hashes."),
        ["RecoveryCreated"] = new("Recovery hashes saved. Enable Windows Hello so a forgotten master can be reset.", "Hashes de recuperación guardados. Activa Windows Hello para poder resetear una maestra olvidada."),
        ["ForgotMaster"] = new("Forgot master password", "Olvidé la contraseña maestra"),
        ["ForgotMasterTitle"] = new("Reset master password", "Restablecer contraseña maestra"),
        ["ForgotMasterBody"] = new("Windows Hello first, then the recovery key or the 7-word phrase. After that Stem asks for a new master and re-encrypts the vault. Shamir cards still reconstruct the old master if you have two of them.", "Primero Windows Hello, luego la recovery key o la frase de 7 palabras. Después Stem pide una maestra nueva y vuelve a cifrar la bóveda. Las tarjetas Shamir siguen reconstruyendo la maestra vieja si tienes dos."),
        ["RecoverySecretTitle"] = new("Recovery key or 7-word phrase", "Recovery key o frase de 7 palabras"),
        ["RecoverySecretHint"] = new("Fill one field. Stem stores only hashes, so a guess is checked locally with Argon2id.", "Rellena un campo. Stem solo guarda hashes, así que una prueba se comprueba aquí con Argon2id."),
        ["NewMasterTitle"] = new("Choose a new master password", "Elige una contraseña maestra nueva"),
        ["NewMasterHint"] = new("At least 12 characters, not repetitive. Stem re-encrypts the whole vault with a new Argon2id key. A USB unlock stick must be prepared again. Shamir cards still reconstruct the previous master.", "Mínimo 12 caracteres, sin repeticiones. Stem vuelve a cifrar toda la bóveda con una clave Argon2id nueva. Hay que preparar otra vez una llave USB. Las tarjetas Shamir siguen reconstruyendo la maestra anterior."),
        ["ChangeMasterTitle"] = new("Master password", "Contraseña maestra"),
        ["ChangeMasterButton"] = new("Change master password", "Cambiar contraseña maestra"),
        ["ChangeMasterHow"] = new("Stem re-encrypts the vault with a new Argon2id key. USB unlock is removed. Windows Hello is turned off until you enable it again. Shamir cards still reconstruct the old master — print new ones. Recovery key and phrase still work after Hello is back on. Stem requires a new master at least once a year.", "Stem vuelve a cifrar la bóveda con una clave Argon2id nueva. Se quita el desbloqueo USB. Windows Hello se apaga hasta que lo actives otra vez. Las tarjetas Shamir siguen reconstruyendo la maestra vieja: imprime otras. La recovery key y la frase siguen sirviendo cuando Hello vuelva a estar activo. Stem pide una maestra nueva al menos una vez al año."),
        ["ChangeMasterConfirmTitle"] = new("Change the master password?", "¿Cambiar la contraseña maestra?"),
        ["ChangeMasterConfirmBody"] = new("The vault is re-encrypted on this PC. USB unlock is removed. Windows Hello is turned off until you enable it again. Old Shamir cards reconstruct the previous master, not this one. Print new cards. This is not reversible. Default is Cancel.", "La bóveda se vuelve a cifrar en este PC. Se quita el USB. Windows Hello se apaga hasta que lo actives otra vez. Las tarjetas Shamir viejas reconstruyen la maestra anterior, no esta. Imprime otras. Esto no se deshace. Cancelar es la opción por defecto."),
        ["ChangeMasterConfirm"] = new("Change master", "Cambiar maestra"),
        ["ChangeMasterCurrentTitle"] = new("Current master password", "Contraseña maestra actual"),
        ["ChangeMasterCurrentHeader"] = new("Type the current master", "Escribe la maestra actual"),
        ["ChangeMasterCurrentHint"] = new("This proves you are the person at this PC. It is checked only in memory.", "Esto demuestra que eres tú en este PC. Solo se comprueba en memoria."),
        ["MasterSamePassword"] = new("Choose a different master password.", "Elige una contraseña maestra distinta."),
        ["MasterWrongCurrent"] = new("That is not the current master password.", "Esa no es la contraseña maestra actual."),
        ["MasterChanged"] = new("New master set. Re-enable Windows Hello and prepare a USB stick if you used them. Print new Shamir cards.", "Maestra nueva. Vuelve a activar Windows Hello y prepara un USB si los usabas. Imprime tarjetas Shamir nuevas."),
        ["MasterRotationDue"] = new("The master password is more than a year old. Stem will lock again until you choose a new one.", "La maestra tiene más de un año. Stem volverá a bloquear hasta que elijas una nueva."),
        ["MasterRotationSoon"] = new("{0} day(s) left to change the master password (yearly).", "Quedan {0} día(s) para cambiar la maestra (una vez al año)."),
        ["MasterRotationOk"] = new("Master last changed {0}. {1} day(s) until the yearly change.", "Maestra cambiada el {0}. Quedan {1} día(s) para el cambio anual."),
        ["MasterRotationStatusOverdue"] = new("Overdue — change the master now. Stem will not stay unlocked with a year-old master.", "Vencida — cambia la maestra ahora. Stem no se queda desbloqueada con una maestra de más de un año."),
        ["MasterRotationHow"] = new("Stem requires a new master at least once a year. The date is stored inside the encrypted vault.", "Stem pide una maestra nueva al menos una vez al año. La fecha se guarda dentro de la bóveda cifrada."),
        ["MasterRotationLocked"] = new("The vault locked because the master password must be changed every year.", "La bóveda se bloqueó porque la maestra hay que cambiarla cada año."),
        ["MasterRotationDueTitle"] = new("Yearly master change", "Cambio anual de maestra"),
        ["MasterRotationDueBody"] = new("This vault's master is older than a year. Choose a new one now. USB unlock is removed and Windows Hello is turned off until you enable it again. Old Shamir cards reconstruct the previous master. Cancel locks the vault.", "La maestra de esta bóveda tiene más de un año. Elige una nueva ahora. Se quita el USB y Windows Hello se apaga hasta que lo actives. Las tarjetas Shamir viejas reconstruyen la maestra anterior. Cancelar bloquea la bóveda."),
        ["HealthMasterOverdue"] = new("Master password is more than a year old. Change it in Protect.", "La maestra tiene más de un año. Cámbiala en Proteger."),
        ["HealthMasterSoon"] = new("Master password should be changed in {0} day(s).", "La maestra debería cambiarse en {0} día(s)."),
        ["RecoveryNeedsHello"] = new("Forgotten-master reset needs Windows Hello on this PC, plus the recovery key or phrase. Unlock with the master once and enable Hello in Protect, or use two Shamir cards.", "Resetear la maestra olvidada necesita Windows Hello en este PC, más la recovery key o la frase. Desbloquea una vez con la maestra y activa Hello en Proteger, o usa dos tarjetas Shamir."),
        ["RecoveryNotConfigured"] = new("This vault has no recovery hashes yet.", "Esta bóveda aún no tiene hashes de recuperación."),
        ["RecoveryWrong"] = new("That recovery key or phrase does not match.", "Esa recovery key o frase no coincide."),
        ["RecoveryHelloFirst"] = new("Confirm Windows Hello to reset the master password", "Confirma Windows Hello para restablecer la maestra"),
        ["RecoveryMasterChanged"] = new("New master password set. The vault was re-encrypted on this PC. USB unlock was cleared if it was on.", "Maestra nueva. La bóveda se volvió a cifrar en este PC. Si había desbloqueo USB, se quitó."),
        ["RecoveryCouldNotReset"] = new("Could not reset the master password.", "No se pudo restablecer la contraseña maestra."),
        ["RecoveryKitReady"] = new("Write down the recovery key and 7-word phrase. Stem will not show them again.", "Anota la recovery key y la frase de 7 palabras. Stem no las volverá a mostrar."),
        ["BrowserHelper"] = new("Install in your browser", "Instalar en tu navegador"),
        ["BrowserHelperHint"] = new("Tap your browser. Stem opens a short guide and loads the helper. Close that tab — you are ready. Keep Stem open while you browse.", "Toca tu navegador. Stem abre una guía corta y carga el ayudante. Cierra esa pestaña y listo. Deja Stem abierto mientras navegas."),
        ["BrowserInstallWhy"] = new("Browsers block silent installs, so Stem launches the browser with the helper loaded and a guide page. If the Stem icon is missing after a full browser restart, tap Install again, or use Load unpacked from Advanced. Firefox Release still drops unsigned add-ons when it quits.", "Los navegadores bloquean instalaciones silenciosas, así que Stem abre el navegador con el ayudante cargado y una guía. Si el icono de Stem falta tras cerrar el navegador por completo, toca Instalar otra vez, o usa Cargar descomprimida en Avanzado. Firefox Release suelta los complementos sin firmar al salir."),
        ["BrowserInstallSteps"] = new("1. Tap Brave, Chrome, or Edge.\n2. Read the guide page, pin Stem from the puzzle menu, close the tab.\n3. In Stem, enable Windows Hello in Protect. Fill from the helper: confirm Hello (then the number pad if Stem asks).", "1. Toca Brave, Chrome o Edge.\n2. Lee la guía, fija Stem en el menú de puzzle y cierra la pestaña.\n3. En Stem, activa Windows Hello en Proteger. Para rellenar desde el ayudante: confirma Hello (y el teclado numérico si Stem lo pide)."),
        ["WelcomePageTitle"] = new("Stem is ready", "Stem está listo"),
        ["WelcomeKicker"] = new("Installed on this PC", "Instalado en este PC"),
        ["WelcomeBrand"] = new("Stem Password Generator", "Generador de contraseñas Stem"),
        ["WelcomeHero"] = new("Your passwords stay on this computer.", "Tus contraseñas se quedan en este equipo."),
        ["WelcomeLead"] = new("This tab is only a guide. Close it when you want. Stem stays in the extensions menu (the puzzle). Pin it, then browse as usual.", "Esta pestaña es solo una guía. Ciérrala cuando quieras. Stem se queda en el menú de extensiones (el puzzle). Fíjala y navega con normalidad."),
        ["WelcomeReady"] = new("The helper is loaded. You can close this page and use your browser. Keep the Stem app open. Unlock the vault to fill; after a sign-in Stem asks to save.", "El ayudante está cargado. Puedes cerrar esta página y usar el navegador. Deja la app Stem abierta. Desbloquea la bóveda para rellenar; tras un inicio Stem pregunta si guardar."),
        ["WelcomeWhatTitle"] = new("What Stem is for", "Para qué sirve Stem"),
        ["WelcomeWhat1Title"] = new("Fill a login", "Rellenar un inicio"),
        ["WelcomeWhat1Body"] = new("On a sign-in page, tap Stem (or the Sign in chip) and pick the saved login. After you type a login yourself, Stem asks to save it in the vault.", "En una página de inicio, toca Stem (o el chip Entrar) y elige el login guardado. Si escribes un inicio tú, Stem te pregunta si lo guardas en la bóveda."),
        ["WelcomeWhat2Title"] = new("Create a strong password", "Crear una contraseña fuerte"),
        ["WelcomeWhat2Body"] = new("Starting an account? Stem can generate a secret, save it in your vault, and put it in the form.", "¿Cuenta nueva? Stem puede generar un secreto, guardarlo en tu bóveda y ponerlo en el formulario."),
        ["WelcomeWhat3Title"] = new("No Stem cloud", "Sin nube de Stem"),
        ["WelcomeWhat3Body"] = new("No Stem account. No server of ours. The helper only talks to the Stem app on this PC.", "Sin cuenta Stem. Sin servidor nuestro. El ayudante solo habla con la app Stem en este PC."),
        ["WelcomeHowTitle"] = new("How it works", "Cómo funciona"),
        ["WelcomeHowBody"] = new("The extension never holds your master key. It asks the Stem app. Unlock Stem (master + human pad, once per hour). The green badge means the vault is ready. Then tap Stem on the site, or press Ctrl+Shift+L. After a sign-in, save when Stem asks.", "La extensión nunca guarda la maestra. Pregunta a la app Stem. Desbloquea Stem (maestra + pad humano, una vez por hora). El distintivo verde significa que la bóveda está lista. Luego toca Stem en el sitio, o pulsa Ctrl+Shift+L. Tras un inicio, guarda cuando Stem lo pida."),
        ["WelcomeStepsTitle"] = new("The useful bits", "Lo esencial"),
        ["WelcomeStep1Title"] = new("Unlock Stem", "Desbloquea Stem"),
        ["WelcomeStep1Body"] = new("Open the Stem app, enter the master password, finish the human pad. Cipher and Generate still work while locked; filling logins does not.", "Abre la app Stem, escribe la maestra y termina el pad humano. Cifrar y Generar siguen funcionando bloqueado; rellenar inicios no."),
        ["WelcomeStep2Title"] = new("Pin the icon", "Fija el icono"),
        ["WelcomeStep2Body"] = new("Puzzle menu → Stem Password Generator → pin. One tap on every login page after that.", "Menú de puzzle → Generador de contraseñas Stem → fijar. Un toque en cada página de inicio después."),
        ["WelcomeStep3Title"] = new("Fill or create", "Rellena o crea"),
        ["WelcomeStep3Body"] = new("Sign in: choose the matching login, or tap Sign in with Stem. After you log in, Stem asks to save. Sign up: let Stem create and save a password.", "Entrar: elige el login que coincide, o toca Entrar con Stem. Cuando inicies sesión, Stem pregunta si guardar. Registrarte: deja que Stem cree y guarde una contraseña."),
        ["WelcomeStep4Title"] = new("Close this tab", "Cierra esta pestaña"),
        ["WelcomeStep4Body"] = new("You are done. If the icon is missing after you fully quit the browser, tap Install in Stem once more — browsers will not let an app lock an extension in forever.", "Listo. Si el icono falta después de cerrar el navegador por completo, toca Instalar en Stem otra vez: los navegadores no dejan que una app deje la extensión para siempre."),
        ["WelcomeLocalBody"] = new("Generate, vault, cipher, and this helper all stay on this PC.", "Generar, bóveda, cifrar y este ayudante se quedan en este PC."),
        ["WelcomeDone"] = new("You can close this tab and use your browser.", "Puedes cerrar esta pestaña y usar tu navegador."),
        ["BrowserInstallBrave"] = new("Install in Brave", "Instalar en Brave"),
        ["BrowserInstallProgressStarting"] = new("Starting install…", "Empezando la instalación…"),
        ["BrowserInstallProgressFinding"] = new("Looking for the browser…", "Buscando el navegador…"),
        ["BrowserInstallProgressCopying"] = new("Copying the helper onto this PC…", "Copiando el ayudante en este PC…"),
        ["BrowserInstallProgressWelcome"] = new("Writing the guide page…", "Escribiendo la página de guía…"),
        ["BrowserInstallProgressPinning"] = new("Registering Stem with the browser…", "Registrando Stem en el navegador…"),
        ["BrowserInstallProgressClosing"] = new("Closing the browser so Stem can load…", "Cerrando el navegador para que Stem pueda cargarse…"),
        ["BrowserInstallProgressLaunching"] = new("Opening the browser with Stem…", "Abriendo el navegador con Stem…"),
        ["BrowserInstallProgressLine"] = new("{0}% — {1}", "{0} % — {1}"),
        ["BrowserInstallEdge"] = new("Install in Microsoft Edge", "Instalar en Microsoft Edge"),
        ["BrowserInstallChrome"] = new("Install in Google Chrome", "Instalar en Google Chrome"),
        ["BrowserInstallFirefox"] = new("Install in Firefox", "Instalar en Firefox"),
        ["BrowserInstallOpera"] = new("Install in Opera", "Instalar en Opera"),
        ["BrowserInstallMore"] = new("More browsers", "Más navegadores"),
        ["BrowserInstallAdvanced"] = new("Advanced", "Avanzado"),
        ["BrowserInstallOperaGx"] = new("Opera GX", "Opera GX"),
        ["BrowserInstallVivaldi"] = new("Vivaldi", "Vivaldi"),
        ["BrowserInstallChromium"] = new("Chromium", "Chromium"),
        ["BrowserInstallYandex"] = new("Yandex Browser", "Yandex Browser"),
        ["BrowserInstallArc"] = new("Arc", "Arc"),
        ["BrowserInstallTor"] = new("Tor Browser", "Tor Browser"),
        ["BrowserInstallWaterfox"] = new("Waterfox", "Waterfox"),
        ["BrowserInstallMaxthon"] = new("Maxthon", "Maxthon"),
        ["BrowserInstallAvast"] = new("Avast Secure Browser", "Avast Secure Browser"),
        ["BrowserInstallEpic"] = new("Epic Privacy Browser", "Epic Privacy Browser"),
        ["BrowserInstallUc"] = new("UC Browser", "UC Browser"),
        ["BrowserInstallDuckDuckGo"] = new("DuckDuckGo Browser", "DuckDuckGo Browser"),
        ["BrowserInstallMoreHint"] = new("Same three taps as Brave if the browser is Chromium-based. Tor and Waterfox use Firefox’s temporary add-on. DuckDuckGo often hides Load unpacked; if you do not see it, use Brave.", "Los mismos tres toques que en Brave si el navegador es Chromium. Tor y Waterfox usan el complemento temporal de Firefox. DuckDuckGo suele ocultar Cargar descomprimida; si no lo ves, usa Brave."),
        ["BrowserOpenFolder"] = new("Open extension folder", "Abrir carpeta de la extensión"),
        ["BrowserCopyFolder"] = new("Copy folder path", "Copiar ruta de la carpeta"),
        ["BrowserPackedHow"] = new("Packed files survive Stem rebuilds. Save stem-helper.zip for Brave, Chrome, and Edge (unzip, then Load unpacked once). Save stem-helper.xpi for Firefox. Chrome/Edge/Firefox stores are not listed yet; these archives are what you would upload.", "Los archivos empaquetados sobreviven a reconstruir Stem. Guarda stem-helper.zip para Brave, Chrome y Edge (descomprime y Cargar descomprimida una vez). Guarda stem-helper.xpi para Firefox. Aún no está en las tiendas; esos archivos son los que subirías."),
        ["BrowserSaveZip"] = new("Save Chromium zip", "Guardar zip de Chromium"),
        ["BrowserSaveXpi"] = new("Save Firefox .xpi", "Guardar .xpi de Firefox"),
        ["BrowserOpenPacked"] = new("Open packed folder", "Abrir carpeta empaquetada"),
        ["BrowserZipFileType"] = new("Chromium extension zip", "Zip de extensión Chromium"),
        ["BrowserXpiFileType"] = new("Firefox add-on (.xpi)", "Complemento Firefox (.xpi)"),
        ["BrowserPackedOpened"] = new("Packed folder opened. stem-helper.zip is Chromium; stem-helper.xpi is Firefox.", "Carpeta empaquetada abierta. stem-helper.zip es Chromium; stem-helper.xpi es Firefox."),
        ["BrowserPackedZipSaved"] = new("Chromium zip saved. Unzip it to a folder you keep, then Load unpacked that folder once.", "Zip de Chromium guardado. Descomprímelo en una carpeta que conserves y Cargar descomprimida esa carpeta una vez."),
        ["BrowserPackedXpiSaved"] = new("Firefox .xpi saved. Open it from Firefox, or use This Firefox → Load Temporary Add-on. Release Firefox forgets unsigned add-ons when it quits.", "Se guardó el .xpi de Firefox. Ábrelo desde Firefox, o usa Este Firefox → Cargar complemento temporal. Firefox Release olvida los complementos sin firmar al salir."),
        ["BrowserInstallFirefoxNote"] = new("Firefox, Waterfox, and Tor: packed .xpi, or This Firefox → Load Temporary Add-on → manifest.json. Release Firefox forgets unsigned add-ons when you quit. Brave, Chrome, and Edge keep a loaded unpacked folder. Tor is portable and may not talk to Stem.", "Firefox, Waterfox y Tor: el .xpi empaquetado, o Este Firefox → Cargar complemento temporal → manifest.json. Firefox Release olvida los complementos sin firmar al salir. Brave, Chrome y Edge conservan la carpeta descomprimida. Tor es portable y a veces no habla con Stem."),
        ["BrowserInstallUnavailableNote"] = new("Safari is not on Windows. Samsung Internet is Android only. Pale Moon does not load Chrome or Firefox WebExtensions. Use Brave, Chrome, Edge, or Firefox on this PC.", "Safari no está en Windows. Samsung Internet es solo Android. Pale Moon no carga extensiones de Chrome o Firefox. En este PC usa Brave, Chrome, Edge o Firefox."),
        ["BrowserInstallOpenedChromium"] = new("Your browser opened with a Stem guide. Close that tab when you want — pin Stem from the puzzle menu and keep this app open. If the icon is missing, close the browser fully and tap Install again.", "Tu navegador abrió una guía de Stem. Cierra esa pestaña cuando quieras: fija Stem en el menú de puzzle y deja esta app abierta. Si no ves el icono, cierra el navegador por completo y toca Instalar otra vez."),
        ["BrowserInstallRestartedChromium"] = new("Brave needed a clean start so Stem could load. Your tabs came back. Pin Stem in the puzzle menu, then close the guide.", "Brave tuvo que arrancar limpio para que Stem pudiera cargarse. Tus pestañas volvieron. Fija Stem en el menú de puzzle y cierra la guía."),
