        ["PublisherStem"] = new("Publisher: Stem", "Publicado por Stem"),
        ["AboutBody1"] = new("Stem is a local password generator and vault for Windows. It creates secrets on this PC, stores optional logins in an encrypted vault, and never uses a Stem cloud. There is no account, no sync server, and no dark-web monitoring.", "Stem es un generador de contraseñas y una bóveda local para Windows. Crea secretos en este PC, guarda inicios de sesión opcionales en una bóveda cifrada y no usa ninguna nube de Stem. No hay cuenta, ni servidor de sincronización, ni monitoreo de la dark web."),
        ["AboutBody2"] = new("Unlocking the vault needs the master password (or Hello / USB) and then Secure Human Verification — a shuffled number pad, once per hour. That is not 2FA. The vault file is Argon2id + AES-256-GCM, wrapped with Windows DPAPI for this user. Paper Shamir cards (any 2 of 3) can reconstruct the master; Stem cannot invent it.", "Desbloquear la bóveda pide la contraseña maestra (o Hello / USB) y luego la verificación humana: un teclado numérico mezclado, una vez por hora. Eso no es 2FA. El archivo usa Argon2id + AES-256-GCM, envuelto con DPAPI de Windows para este usuario. Las tarjetas Shamir en papel (bastan 2 de 3) pueden reconstruir la maestra; Stem no puede inventarla."),
        ["AboutCopyright"] = new("© 2026 Stem. All rights reserved.", "© 2026 Stem. Todos los derechos reservados."),
        ["PrivacyBody"] = new("Stem Password Generator works entirely on your device and does not collect, sell, or transmit personal information. Generated secrets stay in memory unless you save them to the local vault. The vault is encrypted with Argon2id and AES-256-GCM, then wrapped with Windows DPAPI for your user account. Unlocking also requires a local human-presence pad; that is not 2FA and is not sent anywhere. There is no cloud. If the master password is forgotten, Hello plus the recovery key or 7-word phrase, or printed Shamir cards (any 2 of 3), can help — Stem has no server recovery. The app excludes its window from many screenshots, keeps copies out of clipboard history, can auto-clear the clipboard, and auto-locks the vault after inactivity. Screenshot blocking does not stop Remote Desktop or local malware. Optional session history is forgotten when the app closes.", "Stem Password Generator funciona por completo en tu dispositivo y no recopila, vende ni transmite datos personales. Los secretos generados se quedan en memoria salvo que los guardes en la bóveda local. La bóveda se cifra con Argon2id + AES-256-GCM y se envuelve con DPAPI de Windows para tu usuario. El desbloqueo también pide un teclado de presencia humana local; no es 2FA y no se envía a ningún sitio. No hay nube. Si olvidas la maestra, Hello más la recovery key o la frase de 7 palabras, o las tarjetas Shamir impresas (bastan 2 de 3), pueden ayudar: Stem no tiene recuperación en un servidor. La app excluye su ventana de muchas capturas, deja las copias fuera del historial del portapapeles, puede vaciar el portapapeles y bloquea la bóveda tras inactividad. Bloquear capturas no detiene Escritorio remoto ni malware local. El historial opcional de sesión se olvida al cerrar la app."),
        ["PrivacyPolicy"] = new("Privacy Policy", "Política de privacidad"),
        ["ExtensionRegistered"] = new("Browser extension registered on this PC. Reload it, then use Stem on login pages.", "Extensión del navegador registrada en este PC. Recárgala y usa Stem en las páginas de inicio."),
        ["NewLoginTitle"] = new("New login", "Nuevo inicio de sesión"),
        ["MailtoFrom"] = new("Send this from {0}", "Envía esto desde {0}"),
        ["MyVault"] = new("My vault", "Mi bóveda"),
        ["AboutAndAppInfo"] = new("About, tutorials, and frequently asked questions", "Acerca de, tutoriales y preguntas frecuentes"),
        ["AboutWhatTitle"] = new("What Stem does", "Qué hace Stem"),
        ["AboutToolsTitle"] = new("Every tool in Stem", "Cada herramienta de Stem"),
        ["AboutToolsIntro"] = new("The left menu is the map. Each item below is what that page actually does — not a marketing list.", "El menú de la izquierda es el mapa. Cada bloque dice lo que esa página hace de verdad, no un anuncio."),
        ["AboutToolGenerateTitle"] = new("Generate", "Generar"),
        ["AboutToolGenerateBody"] = new("Creates a new secret on this PC with a cryptographic generator.\n• Presets: Everyday (16, no symbols), Strong (20), Extra (32), Wi-Fi, Phrase (six words), PIN (6 digits).\n• Options: length, A–Z, a–z, digits, symbols, skip ambiguous glyphs, no repeats, start with a letter, exclude characters, passphrase separator.\n• Shows strength, entropy, and a local guess-time estimate. That is not a leak check.\n• Copy (Ctrl+Shift+C). Optional auto-clear of the clipboard in Settings.\n• Save the result into the vault when it is unlocked.\n• This-session history stays in memory and is forgotten when Stem closes.\n• Student mode (Settings) explains entropy, reuse in the vault, 2FA, and what happens if you forget the master.", "Crea un secreto nuevo en este PC con un generador criptográfico.\n• Presets: Uso diario (16, sin símbolos), Fuerte (20), Extra (32), Wi-Fi, Frase (seis palabras), PIN (6 dígitos).\n• Opciones: longitud, A–Z, a–z, números, símbolos, evitar ambiguos, sin repeticiones, empezar por letra, excluir caracteres, separador de frase.\n• Muestra fuerza, entropía y un tiempo de adivinanza local. No busca filtraciones.\n• Copiar (Ctrl+Shift+C). En Ajustes puedes vaciar el portapapeles solo.\n• Guarda el resultado en la bóveda cuando esté desbloqueada.\n• El historial de esta sesión vive en memoria y se olvida al cerrar Stem.\n• El modo estudiante (Ajustes) explica entropía, reuso en la bóveda, 2FA y qué pasa si olvidas la maestra."),
        ["CipherTitle"] = new("Encrypt and decrypt text", "Cifrar y descifrar texto"),
        ["CipherIntro"] = new("Type on the left, read the result on the right — like a translator. AES-256-GCM or ChaCha20-Poly1305, then Base64, hex, or binary. Binary is only a view of the same bytes. Local only. Do not reuse the vault master.", "Escribe a la izquierda y lee el resultado a la derecha, como un traductor. AES-256-GCM o ChaCha20-Poly1305, luego Base64, hex o binario. El binario solo muestra los mismos bytes. Solo local. No reutilices la maestra de la bóveda."),
        ["CipherLocalTitle"] = new("Commercial military-grade AEAD", "AEAD de grado militar comercial"),
        ["CipherLocalBody"] = new("AES-256-GCM is the same class used in CNSA / Suite B commercial products. ChaCha20-Poly1305 is the IETF AEAD used by Signal and TLS 1.3. Keys come from Argon2id. This is not a classified Type-1 NSA product. Encoding (Base64 / hex / binary) does not add strength. Forget the password and the note is gone.", "AES-256-GCM es la misma clase que usan productos comerciales CNSA / Suite B. ChaCha20-Poly1305 es el AEAD de IETF que usan Signal y TLS 1.3. Las claves salen de Argon2id. Esto no es un producto clasificado Type-1 de la NSA. El formato (Base64 / hex / binario) no suma fuerza. Si olvidas la contraseña, la nota se pierde."),
        ["CipherPlainTitle"] = new("Plain text", "Texto en claro"),
        ["CipherPlainPlaceholder"] = new("Type or paste the note to encrypt, or read the decrypt result here.", "Escribe o pega la nota a cifrar, o lee aquí el resultado al descifrar."),
        ["CipherCopyPlain"] = new("Copy plain text", "Copiar texto en claro"),
        ["CipherPasswordTitle"] = new("Cipher password and language", "Contraseña del cifrado e idioma"),
        ["CipherPasswordHeader"] = new("Password (12+ characters)", "Contraseña (12+ caracteres)"),
        ["CipherConfirmHeader"] = new("Confirm password", "Confirmar contraseña"),
        ["CipherAlgorithmHeader"] = new("Cipher", "Cifrado"),
        ["CipherLanguageHeader"] = new("Output language", "Idioma de salida"),
        ["CipherAlgAes"] = new("AES-256-GCM", "AES-256-GCM"),
        ["CipherAlgChaCha"] = new("ChaCha20-Poly1305", "ChaCha20-Poly1305"),
        ["CipherLangBase64"] = new("Base64", "Base64"),
        ["CipherLangHex"] = new("Hex", "Hex"),
        ["CipherLangBinary"] = new("Binary", "Binario"),
        ["CipherEncrypt"] = new("Encrypt", "Cifrar"),
        ["CipherDecrypt"] = new("Decrypt", "Descifrar"),
        ["CipherSwap"] = new("Swap direction", "Invertir dirección"),
        ["CipherSourcePlaceholderEncrypt"] = new("Type or paste the note", "Escribe o pega la nota"),
        ["CipherSourcePlaceholderDecrypt"] = new("Paste the ciphertext", "Pega el texto cifrado"),
        ["CipherResultPlaceholderEncrypt"] = new("Encryption", "Cifrado"),
        ["CipherResultPlaceholderDecrypt"] = new("Decryption", "Descifrado"),
        ["CipherCopySource"] = new("Copy source", "Copiar origen"),
        ["CipherCopyResult"] = new("Copy result", "Copiar resultado"),
        ["CipherClearAll"] = new("Clear everything", "Limpiar todo"),
        ["CipherCipherTitle"] = new("Ciphertext", "Texto cifrado"),
        ["CipherCipherPlaceholder"] = new("Encrypted output appears here. Paste a Stem ciphertext to decrypt.", "Aquí sale el cifrado. Pega un texto cifrado de Stem para descifrar."),
        ["CipherCopyCipher"] = new("Copy ciphertext", "Copiar texto cifrado"),
        ["CipherNeedText"] = new("Type the text to encrypt.", "Escribe el texto a cifrar."),
        ["CipherNeedCipher"] = new("Paste the ciphertext to decrypt.", "Pega el texto cifrado para descifrar."),
        ["CipherPasswordShort"] = new("The cipher password must be at least 12 characters.", "La contraseña del cifrado debe tener al menos 12 caracteres."),
        ["CipherPasswordSimple"] = new("That password is too repetitive. Use at least 4 different characters.", "Esa contraseña se repite demasiado. Usa al menos 4 caracteres distintos."),
        ["CipherPasswordMismatch"] = new("The password and confirmation do not match.", "La contraseña y la confirmación no coinciden."),
        ["CipherTooLarge"] = new("That note is larger than 256 KB.", "Esa nota supera los 256 KB."),
        ["CipherAlgUnavailable"] = new("That cipher is not available on this PC.", "Ese cifrado no está disponible en este PC."),
        ["CipherWorking"] = new("Deriving the key with Argon2id…", "Derivando la clave con Argon2id…"),
        ["CipherEncrypted"] = new("Encrypted on this PC. Copy the ciphertext and keep the password.", "Cifrado en este PC. Copia el texto cifrado y guarda la contraseña."),
        ["CipherDecrypted"] = new("Decrypted on this PC.", "Descifrado en este PC."),
        ["CipherWrongPassword"] = new("Wrong password or damaged ciphertext.", "Contraseña incorrecta o texto cifrado dañado."),
        ["CipherFailed"] = new("Could not run the cipher.", "No se pudo ejecutar el cifrado."),
        ["CipherCopiedPlain"] = new("Plain text copied.", "Texto en claro copiado."),
        ["CipherCopiedCipher"] = new("Ciphertext copied.", "Texto cifrado copiado."),
        ["CipherCleared"] = new("Cleared from this screen. Nothing was stored.", "Se limpió esta pantalla. No se guardó nada."),
        ["CipherSwapped"] = new("Direction swapped. The note boxes were cleared. The password stayed.", "Se invirtió la dirección. Se vaciaron las cajas de la nota. La contraseña se quedó."),
        ["AboutToolCheckTitle"] = new("Check", "Comprobar"),
        ["AboutToolCheckBody"] = new("Rates a password, PIN, or phrase you already have — local math first.\n• Detects common secrets, sequences (1234, qwerty), repeats, years, short length, and thin variety.\n• Optional Have I Been Pwned button: k-anonymity range query (hash prefix only, never the password). Off until you tap it. Not a dark-web scan.\n• A “strong” local result can still be reused or already leaked.", "Valora una contraseña, un PIN o una frase que ya tengas — primero matemática local.\n• Detecta secretos comunes, secuencias (1234, qwerty), repeticiones, años, poca longitud y poca variedad.\n• Botón opcional de Have I Been Pwned: consulta k-anónima (solo prefijo del hash, nunca la contraseña). Apagado hasta que pulses. No es un rastreo de dark web.\n• Un resultado local “fuerte” igual puede estar reutilizado o filtrado."),
        ["AboutToolCipherTitle"] = new("Cipher", "Cifrar"),
        ["AboutToolCipherBody"] = new("Encrypts and decrypts a note on this PC. Independent of the vault file.\n• Two columns like a translator: type on the left, read the result on the right. The swap button flips encrypt ↔ decrypt, clears both note boxes, and keeps the password.\n• Algorithms: AES-256-GCM (CNSA / Suite B commercial class) or ChaCha20-Poly1305 (IETF / Signal / TLS 1.3). Not a classified Type-1 product.\n• Key derivation: Argon2id. Password 12+ characters with at least 4 different characters. Confirmation is shown only when encrypting. Algorithm and KDF parameters are bound as AEAD associated data.\n• Output languages are encodings of the same ciphertext: Base64, hex, or binary (0 and 1). Switching language does not add security.\n• Decrypt tries Base64, hex, and binary and only accepts a Stem header. Wrong password or a flipped bit fails closed. Editing the note clears a stale ciphertext.\n• Nothing is saved. Clear wipes this screen. Do not log or screenshot the password.", "Cifra y descifra una nota en este PC. Independiente del archivo de la bóveda.\n• Dos columnas como un traductor: escribes a la izquierda y lees el resultado a la derecha. El botón de intercambio invierte cifrar ↔ descifrar, vacía las dos cajas de la nota y deja la contraseña.\n• Algoritmos: AES-256-GCM (clase comercial CNSA / Suite B) o ChaCha20-Poly1305 (IETF / Signal / TLS 1.3). No es un producto clasificado Type-1.\n• Derivación: Argon2id. Contraseña de 12+ caracteres con al menos 4 distintos. La confirmación solo se ve al cifrar. Algoritmo y KDF van atados como associated data del AEAD.\n• Los idiomas de salida son encodings del mismo ciphertext: Base64, hex o binario (0 y 1). Cambiar de idioma no suma seguridad.\n• Al descifrar se prueban Base64, hex y binario y solo vale un encabezado Stem. Contraseña mala o un bit cambiado fallan cerrado. Editar la nota borra un cifrado viejo.\n• No se guarda nada. Limpiar borra esta pantalla. No registres ni captures la contraseña."),
        ["AboutToolVaultTitle"] = new("Vault", "Bóveda"),
        ["AboutToolVaultBody"] = new("The main security boundary. While it is locked, logins, the multimedia vault, autofill, and clipboard of vault secrets cannot be read.\n• Create a person (up to 8 on this PC) and a master password.\n• Unlock: master, Windows Hello, or a Stem USB key — then the shuffled human-verification pad. The master alone does not open the vault.\n• Optional phone-style QWERTY for the master: Shift for a capital (double-tap for caps lock), 123 for numbers and symbols. Harder for simple keyloggers; not a shield against malware.\n• Item types: login (with TOTP), hide-my-email alias, card, note, identity, recovery codes, Wi-Fi (QR), API / SSH / .env. Optional folders are labels only — not a second lock.\n• Each item records created, last used, and (for passwords) last changed. After 1 year Stem asks you to change that password. Time is this PC’s clock, bounded by Google Public NTP / Cloudflare; nothing from the vault is sent.\n• Activity (Registros): its own subsection under Vault. Only after unlock with the master (or Hello / USB) and the human pad. Failed unlocks, copy/autofill use, and entry changes. Never stores the typed master or any password.\n• Multimedia vault (baúl): its own subsection under Vault, with photo, video, audio, and file galleries (tags, date added, size). AES-256-GCM blobs. Explorer only sees random .spgm names. Same vault lock, not a second lock.\n• Attachments, drag-and-drop seal, password history, search, copy, autofill into another window.\n• Lock, idle auto-lock, minimize lock, and Windows session lock wipe the session. Panic: Ctrl+Shift+L.", "La frontera principal de seguridad. Mientras esté bloqueada, los inicios, el baúl multimedia, el autofill y el portapapeles de secretos no se pueden leer.\n• Crea una persona (hasta 8 en este PC) y una contraseña maestra.\n• Desbloqueo: maestra, Windows Hello o llave USB de Stem, y luego el teclado mezclado de verificación humana. La maestra sola no abre la bóveda.\n• Teclado tipo teléfono para la maestra: Mayús para una mayúscula (doble toque para bloqueo), 123 para números y símbolos. Más difícil para keyloggers simples; no para malware.\n• Tipos: inicio (con TOTP), alias para ocultar el correo, tarjeta, nota, identidad, códigos de recuperación, Wi-Fi (QR), API / SSH / .env. Las carpetas son solo etiquetas, no un segundo candado.\n• Cada ítem anota creación, último uso y (si hay contraseña) el último cambio. A los 12 meses Stem pide cambiarla. La hora es la de este PC, acotada con NTP público de Google / Cloudflare; de la bóveda no se envía nada.\n• Registros: un apartado propio bajo Bóveda. Solo después de desbloquear con la maestra (o Hello / USB) y el teclado humano. Desbloqueos fallidos, uso (copiar / autocompletar) y cambios de entradas. Nunca guarda la maestra escrita ni ninguna contraseña.\n• Baúl multimedia: un apartado propio bajo Bóveda, con galerías de fotos, video, audio y archivos (etiquetas, fecha de entrada, tamaño). Blobs AES-256-GCM. El Explorador solo ve nombres .spgm al azar. El mismo candado de la bóveda, no uno extra.\n• Adjuntos, sellar al soltar un archivo, historial de contraseñas, búsqueda, copiar, autofill a otra ventana.\n• Bloqueo, auto-bloqueo por inactividad, al minimizar y al bloquear Windows. Pánico: Ctrl+Shift+L."),
        ["AboutToolProtectTitle"] = new("Protect", "Proteger"),
        ["AboutToolProtectBody"] = new("Vault tools that need an unlocked vault.\n• Security center: reused, weak, or incomplete logins on this PC.\n• People on this PC: separate vault folders. Names are visible; Hello cannot tell people apart.\n• Mailboxes and hide-my-email aliases.\n• Import Chrome, Edge, Firefox, Bitwarden, 1Password CSV, or KeePass (.kdbx / CSV). Export is still a plaintext CSV.\n• Change the master while unlocked (USB and Hello must be set up again). Yearly change is required.\n• Portable copy (.spgp) for another PC: same master, not DPAPI-bound. Multimedia baúl stays here.\n• Shamir paper cards (any 2 of 3 reconstruct the master).\n• Encrypted share of one item or a vault copy; import a share.\n• Emergency kit.\n• Recovery key / 7-word phrase hashes, Windows Hello wrap.\n• Decoy vault and panic lock — for a quick glance, not forensics. The real vault file still exists.", "Herramientas de la bóveda que piden la bóveda desbloqueada.\n• Centro de seguridad: inicios reutilizados, débiles o incompletos en este PC.\n• Personas en este PC: carpetas de bóveda aparte. Los nombres se ven; Hello no distingue personas.\n• Buzones y alias para ocultar el correo.\n• Importa CSV de Chrome, Edge, Firefox, Bitwarden, 1Password o KeePass (.kdbx / CSV). La exportación sigue siendo un CSV en texto plano.\n• Cambia la maestra con la bóveda abierta (hay que rehacer USB y Hello). El cambio anual es obligatorio.\n• Copia portable (.spgp) para otro PC: misma maestra, no atada a DPAPI. El baúl multimedia se queda aquí.\n• Tarjetas Shamir en papel (bastan 2 de 3 para reconstruir la maestra).\n• Envío cifrado de un ítem o de una copia de la bóveda; importar un envío.\n• Kit de emergencia.\n• Hashes de recovery key / frase de 7 palabras, envoltorio de Windows Hello.\n• Bóveda señuelo y bloqueo de pánico: para una mirada rápida, no contra un análisis forense. El archivo real sigue en el PC."),
        ["AboutToolUsbTitle"] = new("USB key", "Llave USB"),
        ["AboutToolUsbBody"] = new("Puts a Stem unlock blob on a regular flash drive (AES-256-GCM + Argon2id) protected by a PIN.\n• This is not FIDO2, not a YubiKey, and Chrome will not treat the stick as a hardware security key.\n• Optional format like Explorer: exFAT, FAT32, or NTFS.\n• Unlocking with USB still requires Secure Human Verification afterwards, at most once per hour.\n• Losing the stick is not the same as losing the vault; it is an extra unlock method.", "Pone un blob de desbloqueo de Stem en un USB común (AES-256-GCM + Argon2id) protegido con un PIN.\n• No es FIDO2, no es YubiKey, y Chrome no va a tratar el palo como llave de hardware.\n• Formato opcional como el Explorador: exFAT, FAT32 o NTFS.\n• Desbloquear con USB igual pide la verificación humana después, como mucho una vez por hora.\n• Perder el palo no es perder la bóveda; es un método extra de desbloqueo."),
        ["AboutToolSettingsTitle"] = new("Settings", "Ajustes"),
        ["AboutToolSettingsBody"] = new("App-wide preferences.\n• Language: English or Español.\n• Theme: system, light, or dark.\n• Clear clipboard after copy.\n• Auto-lock the vault after inactivity (and related window/session locks).\n• Student mode.\n• Stay in the system tray; tray generate/copy and fill.\n• Global hotkeys: Ctrl+Alt+S generate, Ctrl+Alt+F fill.\n• Panic lock notes (Ctrl+Shift+L).\n• Erase all Stem data: three warnings, master password, then the shuffled pad. First-run after that.", "Preferencias de toda la app.\n• Idioma: English o Español.\n• Tema: sistema, claro u oscuro.\n• Vaciar el portapapeles tras copiar.\n• Auto-bloquear la bóveda por inactividad (y bloqueos de ventana/sesión).\n• Modo estudiante.\n• Quedar en la bandeja; generar/copiar y rellenar desde ahí.\n• Atajos globales: Ctrl+Alt+S genera, Ctrl+Alt+F rellena.\n• Notas del bloqueo de pánico (Ctrl+Shift+L).\n• Borrar todos los datos de Stem: tres avisos, maestra y teclado mezclado. Luego queda como recién instalado."),
        ["AboutGuidesTitle"] = new("Tutorials", "Tutoriales"),
        ["AboutGuidesIntro"] = new("Open a topic, follow the steps in order. Destructive dialogs default to Cancel. Do not screenshot recovery material.", "Abre un tema y sigue los pasos en orden. Los diálogos destructivos dejan Cancelar por defecto. No hagas captura del material de recuperación."),
        ["AboutGuideGenerateTitle"] = new("Tutorial: Generate a secret", "Tutorial: generar un secreto"),
        ["AboutGuideGenerateBody"] = new("1. Open Generate in the left menu.\n2. Tap a preset (Everyday, Strong, Extra, Wi-Fi, Phrase, or PIN) or set length and character classes yourself.\n3. Stem fills the box. Read strength, entropy, and guess time — those are local estimates.\n4. Copy with the button or Ctrl+Shift+C. Turn on “clear clipboard” in Settings if you want the copy to vanish after a short time.\n5. If the vault is unlocked, Save to vault stores it as a login. If it is locked, Stem queues it until you unlock.\n6. Optional: expand This session to copy an earlier generate. That list dies when Stem exits.\n7. Ctrl+G generates again. With global hotkeys on, Ctrl+Alt+S generates and copies even from the tray.", "1. Abre Generar en el menú izquierdo.\n2. Pulsa un preset (Uso diario, Fuerte, Extra, Wi-Fi, Frase o PIN) o elige longitud y tipos de carácter.\n3. Stem llena la caja. Mira fuerza, entropía y tiempo de adivinanza: son estimaciones locales.\n4. Copia con el botón o Ctrl+Shift+C. En Ajustes puedes vaciar el portapapeles al cabo de un rato.\n5. Si la bóveda está desbloqueada, Guardar en la bóveda lo deja como inicio. Si está bloqueada, Stem lo deja en cola hasta que desbloquees.\n6. Opcional: abre Esta sesión para copiar una generación anterior. Esa lista muere al salir de Stem.\n7. Ctrl+G genera otra vez. Con atajos globales, Ctrl+Alt+S genera y copia incluso desde la bandeja."),
        ["AboutGuideCheckTitle"] = new("Tutorial: Check a password you invented", "Tutorial: comprobar una contraseña que inventaste"),
        ["AboutGuideCheckBody"] = new("1. Open Check.\n2. Type or paste the secret. Stem classifies it as password, PIN, or phrase.\n3. Read the findings and “what to do next.”\n4. If it is weak or common, go to Generate and make a new one, then save it in the vault.\n5. Optional: tap Check Have I Been Pwned. Stem sends only a SHA-1 prefix (k-anonymity), never the password. Skip it if you are offline. A green local rating is not proof the secret was never leaked.", "1. Abre Comprobar.\n2. Escribe o pega el secreto. Stem lo clasifica como contraseña, PIN o frase.\n3. Lee los avisos y “qué hacer ahora.”\n4. Si es débil o común, ve a Generar, crea una nueva y guárdala en la bóveda.\n5. Opcional: pulsa Consultar Have I Been Pwned. Stem solo envía un prefijo SHA-1 (k-anonimato), nunca la contraseña. Sáltatelo si no hay internet. Un resultado local bueno no prueba que nunca se haya filtrado."),
        ["AboutGuideCipherTitle"] = new("Tutorial: Encrypt a note", "Tutorial: cifrar una nota"),
        ["AboutGuideCipherBody"] = new("1. Open Cipher.\n2. Choose AES-256-GCM or ChaCha20-Poly1305, and an output language (Base64, hex, or binary).\n3. Type the note on the left. Type a 12+ character password twice (confirm is only for encrypt). This is not the vault master unless you reuse it (do not).\n4. Tap Encrypt. The right side is the ciphertext. Copy it with the icon. Stem does not store the note.\n5. Tap the swap arrows to decrypt: both note boxes clear, the password stays, the button becomes Decrypt, confirm hides. Paste the ciphertext on the left.\n6. A wrong password fails; Stem cannot recover the note. Encoding is detected when decrypting.", "1. Abre Cifrar.\n2. Elige AES-256-GCM o ChaCha20-Poly1305, y un idioma de salida (Base64, hex o binario).\n3. Escribe la nota a la izquierda. Escribe una contraseña de 12+ caracteres dos veces (la confirmación solo sale al cifrar). No es la maestra de la bóveda salvo que la reutilices (no lo hagas).\n4. Pulsa Cifrar. A la derecha queda el texto cifrado. Cópialo con el icono. Stem no guarda la nota.\n5. Pulsa las flechas para descifrar: se vacían las cajas de la nota, la contraseña se queda, el botón pasa a Descifrar y se oculta la confirmación. Pega el texto cifrado a la izquierda.\n6. Una contraseña mala falla; Stem no puede recuperar la nota. Al descifrar se detecta el encoding."),
        ["AboutGuideVaultTitle"] = new("Tutorial: Create and unlock the vault", "Tutorial: crear y desbloquear la bóveda"),
        ["AboutGuideVaultBody"] = new("1. Open Vault. If this PC has no vault yet, enter a person name and a master password twice (12+ characters). Prefer a long unique phrase you can remember.\n2. Stem shows a recovery key and a 7-word phrase once (again on the next unlock if you cancelled the human pad at create). Write them down. Stem stores hashes, not the words.\n3. To unlock later: choose the person, enter the master (or use Hello / USB). Optional: phone QWERTY (Shift / 123) so a simple keylogger sees fewer physical keys.\n4. After the master is accepted, tap the six digits in order on the shuffled pad. The pad changes after every correct tap. A wrong tap starts a new number. This is not a second password.\n5. Only then the workspace opens. Vault has three subsections: Items (logins, cards, notes…), Multimedia vault, and Activity. Activity is only after unlock and never stores the typed master. Optional folders are labels so a large list stays readable.\n6. Add items with the buttons. For a login you can paste a TOTP secret or otpauth:// URI to get 2FA codes.\n7. Open Multimedia vault under Vault to add photos, video, audio, or files. They stay ciphertext on disk.\n8. Drop a file on the Stem window to seal it. Autofill types into the focused app after you click the username field.\n9. Lock when you walk away. Ctrl+Shift+L is panic lock (optional decoy vault from Protect).", "1. Abre Bóveda. Si este PC aún no tiene, pon un nombre de persona y una maestra dos veces (12+ caracteres). Mejor una frase larga y única que recuerdes.\n2. Stem muestra una vez una recovery key y una frase de 7 palabras (otra vez en el siguiente desbloqueo si cancelaste el teclado humano al crear). Anótalas. Stem guarda hashes, no las palabras.\n3. Para desbloquear: elige la persona, escribe la maestra (o Hello / USB). Opcional: QWERTY de teléfono (Mayús / 123) para que un keylogger simple vea menos teclas físicas.\n4. Cuando la maestra vale, pulsa los seis dígitos en orden en el teclado mezclado. Cambia tras cada toque correcto. Un toque mal empieza un número nuevo. No es una segunda contraseña.\n5. Solo entonces se abre el espacio de trabajo. La bóveda tiene tres apartados: Ítems (inicios, tarjetas, notas…), Baúl multimedia y Registros. Registros solo se abre tras desbloquear y nunca guarda la maestra escrita. Las carpetas opcionales son etiquetas para no perderse en una lista grande.\n6. Agrega ítems con los botones. En un inicio puedes pegar un secreto TOTP o una URI otpauth:// para códigos 2FA.\n7. Abre Baúl multimedia bajo Bóveda para fotos, video, audio o archivos. En disco siguen siendo ciphertext.\n8. Suelta un archivo en la ventana de Stem para sellarlo. Autocompletar escribe en la app en foco cuando haces clic en el usuario.\n9. Bloquea al alejarte. Ctrl+Shift+L es pánico (bóveda señuelo opcional en Proteger)."),
        ["AboutGuideProtectTitle"] = new("Tutorial: Protect and backup", "Tutorial: Proteger y copias"),
        ["AboutGuideProtectBody"] = new("1. Unlock the vault, then open Protect.\n2. Read the security center. Fix reused or weak logins in Vault.\n3. Add another person only if they should have their own vault folder on this PC.\n4. Print Shamir cards and store them apart. Any 2 of 3 rebuild the master. Keep them off this PC’s screenshots.\n5. Optional: enable Windows Hello. Hello is consent plus a wrap on this Windows user — it cannot tell two people apart.\n6. Create an emergency kit and keep it with the paper cards.\n7. CSV import is plaintext. A KeePass .kdbx needs the KeePass password. Delete the source file when you are done.\n8. Change the master in Protect at least once a year. USB and Hello must be set up again. Cancel on an overdue prompt locks the vault.\n9. Decoy vault is for a quick look, not a forensic wipe.", "1. Desbloquea la bóveda y abre Proteger.\n2. Lee el centro de seguridad. Corrige inicios reutilizados o débiles en Bóveda.\n3. Agrega otra persona solo si debe tener su propia carpeta de bóveda en este PC.\n4. Imprime las tarjetas Shamir y sepáralas. Bastan 2 de 3 para reconstruir la maestra. Fuera de capturas de este PC.\n5. Opcional: activa Windows Hello. Hello es consentimiento más un envoltorio de este usuario de Windows: no distingue a dos personas.\n6. Crea un kit de emergencia y guárdalo con las tarjetas de papel.\n7. El CSV es texto plano. Un .kdbx de KeePass pide la contraseña de KeePass. Borra el archivo de origen cuando termines.\n8. Cambia la maestra en Proteger al menos una vez al año. Hay que rehacer USB y Hello. Cancelar un aviso vencido bloquea la bóveda.\n9. El señuelo es para una mirada rápida, no para borrar pruebas forenses."),
        ["AboutGuideUsbTitle"] = new("Tutorial: USB unlock key", "Tutorial: llave USB de desbloqueo"),
        ["AboutGuideUsbBody"] = new("1. Unlock the real vault first.\n2. Open USB key. Read the warning: this stick will not become a FIDO2 key.\n3. Plug in a flash drive, tap Refresh, select it.\n4. Optional: format like Explorer (this erases the stick).\n5. Prepare the Stem key and choose a PIN (not your vault master).\n6. To unlock later: Unlock with USB, enter the PIN, then complete human verification.\n7. You can remove the USB unlock method later from the vault settings on that page.", "1. Desbloquea primero la bóveda real.\n2. Abre Llave USB. Lee el aviso: este palo no se convierte en llave FIDO2.\n3. Conecta un USB, pulsa Actualizar, selecciónalo.\n4. Opcional: formatear como el Explorador (esto borra el palo).\n5. Prepara la llave Stem y elige un PIN (no es la maestra de la bóveda).\n6. Para desbloquear después: Desbloquear con USB, PIN, y luego la verificación humana.\n7. Más tarde puedes quitar el desbloqueo USB en esa misma página."),
        ["AboutGuideSettingsTitle"] = new("Tutorial: Settings and shortcuts", "Tutorial: Ajustes y atajos"),
        ["AboutGuideSettingsBody"] = new("1. Open Settings.\n2. Language and theme apply at once.\n3. Turn on clear-clipboard if you copy secrets often.\n4. Keep auto-lock on unless you are sitting at the PC.\n5. Student mode adds four plain lines after Generate.\n6. Tray: closing the window can hide Stem instead of quitting. Right-click the tray icon to generate, fill, panic, or quit.\n7. Global hotkeys: Ctrl+Alt+S generate+copy, Ctrl+Alt+F fill the focused login (vault must be unlocked).\n8. In-app: Ctrl+G generate, Ctrl+Shift+C copy, Ctrl+Shift+L panic.\n9. Erase all Stem data only if you mean it: unlock, three Cancel-default warnings, master password, shuffled pad. That is first-run, not a forensic wipe of backups you already exported.", "1. Abre Ajustes.\n2. Idioma y tema se aplican al momento.\n3. Activa vaciar portapapeles si copias secretos a menudo.\n4. Deja el auto-bloqueo salvo que estés frente al PC.\n5. El modo estudiante añade cuatro líneas claras tras Generar.\n6. Bandeja: cerrar la ventana puede ocultar Stem en vez de salir. Clic derecho en el icono para generar, rellenar, pánico o salir.\n7. Atajos globales: Ctrl+Alt+S genera y copia, Ctrl+Alt+F rellena el inicio en foco (la bóveda debe estar desbloqueada).\n8. En la app: Ctrl+G generar, Ctrl+Shift+C copiar, Ctrl+Shift+L pánico.\n9. Borrar todos los datos de Stem solo si lo dices en serio: desbloquea, tres avisos con Cancelar por defecto, maestra y teclado mezclado. Eso es primer inicio, no un borrado forense de copias que ya exportaste."),
        ["AboutFaqTitle"] = new("Frequently asked questions", "Preguntas frecuentes"),
        ["AboutFaqIntro"] = new("Short answers. If a sentence sounds absolute, read the matching tutorial — Stem stays honest about Windows limits.", "Respuestas cortas. Si una frase suena absoluta, lee el tutorial: Stem es honesto con los límites de Windows."),
        ["AboutFaqCloudQ"] = new("Does Stem use the cloud or an account?", "¿Stem usa la nube o una cuenta?"),
        ["AboutFaqCloudA"] = new("No. There is no Stem account and no Stem server. Vault files live under your Windows user profile. Sharing is a file you encrypt yourself, not sync.", "No. No hay cuenta de Stem ni servidor de Stem. Los archivos de la bóveda viven en el perfil de tu usuario de Windows. Compartir es un archivo que cifras tú, no una sincronización."),
        ["AboutFaqForgetQ"] = new("What if I forget the master password?", "¿Qué pasa si olvido la contraseña maestra?"),
        ["AboutFaqForgetA"] = new("Stem cannot invent it. Options: Windows Hello plus the recovery key shown at create; Hello plus the 7-word phrase; or any 2 of 3 Shamir paper cards. Without those, the vault stays sealed. There is no email reset.", "Stem no puede inventarla. Opciones: Windows Hello más la recovery key que viste al crear; Hello más la frase de 7 palabras; o 2 de 3 tarjetas Shamir. Sin eso, la bóveda sigue sellada. No hay reset por correo."),
        ["AboutFaqHumanQ"] = new("Is the number pad a second password or 2FA?", "¿El teclado numérico es una segunda contraseña o 2FA?"),
        ["AboutFaqHumanA"] = new("No. The digits are shown on purpose. It is a human-presence step so a recorded click path or a simple bot is less useful. After you complete it, Stem skips it for one hour. It is not MFA. Malware that can see the screen or read Stem’s memory can still attack you.", "No. Los dígitos se muestran a propósito. Es un paso de presencia humana para que un clic grabado o un bot simple sirvan menos. Cuando lo terminas, Stem se lo salta durante una hora. No es MFA. El malware que ve la pantalla o lee la memoria de Stem igual puede atacarte."),
        ["AboutFaqUsbQ"] = new("Is the USB key a YubiKey / FIDO2 key?", "¿La llave USB es una YubiKey / FIDO2?"),
        ["AboutFaqUsbA"] = new("No. A normal flash drive cannot become a hardware security key for Chrome or Windows Hello. Stem only stores an encrypted Stem unlock blob on the stick.", "No. Un USB común no se convierte en llave de hardware para Chrome o Windows Hello. Stem solo guarda en el palo un blob cifrado de desbloqueo de Stem."),
        ["AboutFaqCheckQ"] = new("Does Check tell me if my password leaked?", "¿Comprobar me dice si mi contraseña se filtró?"),
        ["AboutFaqCheckA"] = new("The rating is local. An optional button can query Have I Been Pwned with k-anonymity: Stem sends only the first 5 hex characters of a SHA-1 hash, never the password. It stays off until you tap it. “Not listed” is not a lifetime guarantee. Use a unique generated secret per site anyway.", "La nota es local. Un botón opcional puede consultar Have I Been Pwned con k-anonimato: Stem solo envía los primeros 5 caracteres hex del hash SHA-1, nunca la contraseña. Sigue apagado hasta que pulses. “No aparece” no es garantía para siempre. Usa un secreto generado único por sitio de todos modos."),
        ["AboutFaqCipherQ"] = new("Is Cipher “military encryption,” including binary?", "¿Cifrar es “cifrado militar”, incluso en binario?"),
        ["AboutFaqCipherA"] = new("The algorithms are AES-256-GCM and ChaCha20-Poly1305 with Argon2id — the same class used in commercial military and IETF products. Stem is not a classified Type-1 device. Binary, hex, and Base64 are encodings of the ciphertext, not extra ciphers. Binary does not make the note stronger.", "Los algoritmos son AES-256-GCM y ChaCha20-Poly1305 con Argon2id — la misma clase de productos militares comerciales e IETF. Stem no es un dispositivo clasificado Type-1. Binario, hex y Base64 son encodings del ciphertext, no cifrados extra. El binario no hace la nota más fuerte."),
        ["AboutFaqOtherPcQ"] = new("Can I open this vault on another PC?", "¿Puedo abrir esta bóveda en otro PC?"),
        ["AboutFaqOtherPcA"] = new("Copying vault.spg to another PC will not open: that file is wrapped with DPAPI for this Windows user. In Protect, save a portable copy (.spgp). It uses the same master password and is not bound to this Windows account. On the other PC, create or select a person without a vault, type that master, and open the .spgp file. Hello, USB, and Shamir from the old PC are not inside it. Encrypted shares still use a separate share password.", "Copiar vault.spg a otro PC no abre: ese archivo va envuelto con DPAPI de este usuario de Windows. En Proteger, guarda una copia portable (.spgp). Usa la misma maestra y no está atada a esta cuenta. En el otro PC, crea o elige una persona sin bóveda, escribe esa maestra y abre el .spgp. Hello, USB y Shamir del PC viejo no van dentro. Los envíos cifrados siguen usando otra contraseña."),
        ["AboutFaqPanicQ"] = new("Does panic lock hide the vault from forensics?", "¿El bloqueo de pánico oculta la bóveda de un análisis forense?"),
        ["AboutFaqPanicA"] = new("No. It locks Stem quickly and can open a decoy with fake logins. The real encrypted vault file is still on the disk. It is for a glance, lending a PC, or a checkpoint look.", "No. Bloquea Stem enseguida y puede abrir un señuelo con inicios falsos. El archivo cifrado real sigue en el disco. Sirve para una mirada, prestar el PC o un control."),
        ["AboutFaqMediaQ"] = new("Is the multimedia vault (baúl) a separate lock?", "¿El baúl multimedia es un candado aparte?"),
        ["AboutFaqMediaA"] = new("No. It lives inside the general vault. Until the vault is UNLOCKED (master + human verification), the baúl stays inaccessible. After unlock, it follows the same session.", "No. Vive dentro de la bóveda general. Hasta que la bóveda esté DESBLOQUEADA (maestra + verificación humana), el baúl sigue inaccesible. Después usa la misma sesión."),
        ["AboutFaqCaptureQ"] = new("Are screenshots of Stem blocked?", "¿Las capturas de Stem están bloqueadas?"),
        ["AboutFaqCaptureA"] = new("Stem asks Windows to exclude the window from many capture APIs (Win10 2004+). That does not stop Remote Desktop, some recorders, or malware. Do not treat it as invisibility.", "Stem pide a Windows excluir la ventana de muchas APIs de captura (Win10 2004+). Eso no detiene Escritorio remoto, algunos grabadores ni malware. No lo tomes por invisibilidad."),
        ["AboutFaqExtensionQ"] = new("Can the browser extension fill while the vault is locked?", "¿La extensión puede rellenar con la bóveda bloqueada?"),
        ["AboutFaqExtensionA"] = new("No. Match, fill, and secret requests are refused until the vault is fully unlocked. After a correct master, during human verification, the extension still sees a locked vault.", "No. Match, fill y secret se rechazan hasta que la bóveda esté del todo desbloqueada. Tras una maestra correcta, durante la verificación humana, la extensión sigue viendo la bóveda bloqueada."),
        ["AboutFaqHelloQ"] = new("Is Windows Hello enough without the master?", "¿Windows Hello basta sin la maestra?"),
        ["AboutFaqHelloA"] = new("Hello can unwrap a stored session key after you consent, then human verification still runs. Hello cannot tell two people on this PC apart. Prefer a strong master plus paper backup.", "Hello puede desenvolver una clave de sesión guardada cuando consientes, y luego igual corre la verificación humana. Hello no distingue a dos personas en este PC. Mejor una maestra fuerte más respaldo en papel."),
        ["AboutFaqPeopleQ"] = new("How many people can have a vault on this PC?", "¿Cuántas personas pueden tener bóveda en este PC?"),
        ["AboutFaqPeopleA"] = new("Up to 8 occupants. Each has a separate folder. Display names are visible on the unlock screen. That is not anonymity.", "Hasta 8 ocupantes. Cada uno tiene carpeta propia. Los nombres se ven en la pantalla de desbloqueo. Eso no es anonimato."),
        ["CopyGeneratedSecret"] = new("Copy generated secret", "Copiar el secreto generado")
    };
}
